import './App.css';
import { useState } from "react";
import { motion, AnimatePresence } from "framer-motion";

function App() {
  return (
    <div className="App">
      <Header />
      <EducationSection />
      <WorkExperienceSection />
      <ProjectsSection />
    </div>
  );
}

// Header component
const Header = () => (
  <header>
    <h1>Robert Roskowski</h1>
    <p>Computer Science Student at Michigan State University</p>
    <p>Welcome to my portfolio! Browse my work below.</p>
  </header>
);

// CollapsibleSection Component for slide animations
const CollapsibleSection = ({ title, children }) => {
  const [isOpen, setIsOpen] = useState(false);
  return (
    <section className="section">
      <h2 onClick={() => setIsOpen(prev => !prev)} style={{ cursor: "pointer" }}>
        {title} {isOpen ? "▼" : "►"}
      </h2>
      <AnimatePresence>
        {isOpen && (
          <motion.div
            initial={{ height: 0, opacity: 0 }}
            animate={{ height: 'auto', opacity: 1 }}
            exit={{ height: 0, opacity: 0 }}
            transition={{ duration: 0.5 }}
          >
            {children}
          </motion.div>
        )}
      </AnimatePresence>
    </section>
  );
};

// Education Section using CollapsibleSection
const EducationSection = () => (
  <CollapsibleSection title="Education">
    <div>
      <h3>Bachelor of Science in Computer Science</h3>
      <p>Concentration: Artificial Intelligence</p>
      <p>GPA: 3.97 / 4.0</p>
      <p>Michigan State University, May 2026</p>
      <p>Relevant Coursework: Data Structures & Algorithms, Computer Organization & Architecture, Computer Systems, Software Design & Development, Discrete Mathematics, Linear Algebra, Calculus III, Physics II </p>
    </div>
    <div>
      <h3>Machine Learning Specialization</h3>
      <p>Coursera, DeepLearningAI, Stanford University - 2024</p>
      <p>Relevant Coursework: Supervised Machine Learning, Advanced Learning Algorithms, Unsupervised Learning, Recommender Systems, Reinforcement Learning</p>
    </div>
  </CollapsibleSection>
);

// Work Experience Section using CollapsibleSection
const WorkExperienceSection = () => (
  <CollapsibleSection title="Work Experience">
    <div>
      <h3>Incoming Micr</h3>
      <p>May 2024 - August 2024</p>
      <p>
        Developed a full‑stack synthetic vehicle data generator and advanced data processing algorithms.
      </p>
    </div>
    <div>
      <h3>Software Engineer Intern at BorgWarner</h3>
      <p>May 2024 - August 2024</p>
      <p>
        Developed a full‑stack synthetic vehicle data generator and advanced data processing algorithms.
      </p>
    </div>
    <div>
      <h3>Software Engineer Intern at MyEdMaster LLC</h3>
      <p>June 2023 - August 2023</p>
      <p>
        Created interactive algebra quiz platforms used by thousands of students.
      </p>
    </div>
  </CollapsibleSection>
);

// Projects Section using CollapsibleSection
const ProjectsSection = () => (
  <CollapsibleSection title="Projects">
    <div>
      <h3>Ensemble Multi-Agent Framework</h3>
      <p>
        Winner, Best Developer Tool @ Mhacks 2024. Designed a collaborative multi-agent system using Python, AWS, and GPT-based technology.
      </p>
    </div>
    <div>
      <h3>AI-Powered Desktop and Video Game Assistant</h3>
      <p>
        Built a cross‑platform AI assistant with Electron, Node.js, FastAPI, and Python for desktop and gaming support.
      </p>
    </div>
    <div>
      <h3>Pacman Recreation</h3>
      <p>
        Developed a Pacman recreation using HTML, CSS, and JavaScript.
      </p>
    </div>
  </CollapsibleSection>
);

export default App;
